steps.cmd:
powershell -ep bypass -c "
# Reconnaissance: identify target infrastructure
$target = 'www.{companyName}.com';
$dns = Resolve-DnsName $target -Type A;
Write-Host 'Target Reconnaissance:';
Write-Host \"  Domain : $target\";
Write-Host \"  IP     : $($dns.IPAddress -join ', ')\";
$whois = \"ASN: AS12345 | ISP: {companyName} Hosting | Region: KR\";
Write-Host \"  $whois\";
Write-Host '';
# Check for CDN/WAF
Test-NetConnection $target -Port 80 | Select-Object ComputerName, RemotePort, TcpTestSucceeded | Format-Table -AutoSize;
Test-NetConnection $target -Port 443 | Select-Object ComputerName, RemotePort, TcpTestSucceeded | Format-Table -AutoSize;
Write-Host 'CDN/WAF Detection: None (direct to origin)';
Write-Host '[!] Target is vulnerable to direct flood attacks'"

powershell -ep bypass -c "
# SYN Flood attack simulation
$target = '203.0.113.100';
$port = 80;
Write-Host '=== SYN Flood Attack ===';
Write-Host \"Target: $target`:$port\";
Write-Host \"Method: TCP SYN packets (half-open connections)\";
Write-Host \"Rate  : 50,000 packets/second\";
Write-Host '';
for($i=1; $i -le 6; $i++) {
  $srcIP = \"$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254)\";
  $srcPort = Get-Random -Min 1024 -Max 65535;
  Write-Host \"  [SYN] $srcIP`:$srcPort → $target`:$port | TTL=64 | Window=65535 | Seq=$(Get-Random)\";
}
Write-Host '  ... (49,994 more SYN packets per second)';
Write-Host '';
Write-Host 'SYN Flood effect:';
Write-Host '  - Target TCP connection table exhausted';
Write-Host '  - Legitimate connections cannot be established';
Write-Host '  - Half-open connections timeout slowly (SYN_RECV state)'"

powershell -ep bypass -c "
# UDP Flood attack simulation
$target = '203.0.113.100';
Write-Host '=== UDP Flood Attack ===';
Write-Host \"Target: $target (random ports)\";
Write-Host \"Method: UDP packets with random payloads\";
Write-Host \"Rate  : 100,000 packets/second\";
Write-Host \"Payload: 1400 bytes per packet (max MTU)\";
Write-Host \"Bandwidth: ~1.12 Gbps\";
Write-Host '';
for($i=1; $i -le 6; $i++) {
  $srcIP = \"$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254).$(Get-Random -Min 1 -Max 254)\";
  $dstPort = Get-Random -Min 1 -Max 65535;
  Write-Host \"  [UDP] $srcIP → $target`:$dstPort | Size=1400B | Payload=0x$('{0:X8}' -f (Get-Random))...\";
}
Write-Host '  ... (99,994 more UDP packets per second)';
Write-Host '';
Write-Host 'UDP Flood effect:';
Write-Host '  - Network bandwidth saturation (1.12 Gbps)';
Write-Host '  - ICMP Destination Unreachable floods back';
Write-Host '  - Firewall state table exhaustion'"

powershell -ep bypass -c "
# DNS Amplification attack simulation
Write-Host '=== DNS Amplification Attack ===';
Write-Host 'Method: Spoofed DNS queries to open resolvers';
Write-Host 'Amplification factor: ~50x';
Write-Host '';
Write-Host 'Attack chain:';
Write-Host '  1. Attacker sends small DNS query (60 bytes)';
Write-Host '  2. Source IP spoofed as victim (203.0.113.100)';
Write-Host '  3. Open resolver sends large response (~3000 bytes) to victim';
Write-Host '  4. Amplification: 60B → 3000B (50x amplification)';
Write-Host '';
$resolvers = @('8.8.8.8','1.1.1.1','208.67.222.222','9.9.9.9','64.6.64.6');
foreach($r in $resolvers) {
  Write-Host \"  [DNS-AMP] Query: ANY isc.org → Resolver: $r → Response(3KB) → Victim: 203.0.113.100\";
}
Write-Host '';
Write-Host 'Amplified traffic hitting victim:';
Write-Host '  Query rate    : 20,000 queries/sec (1.2 MB/sec sent)';
Write-Host '  Response rate : 20,000 responses/sec (60 MB/sec received by victim)';
Write-Host '  Amplified BW  : ~480 Mbps hitting victim from legitimate DNS servers'"

powershell -ep bypass -c "
# HTTP Flood (Layer 7) attack simulation
Write-Host '=== HTTP Flood (Layer 7 DDoS) ===';
Write-Host \"Target: https://www.{companyName}.com\";
Write-Host 'Method: Distributed HTTP GET/POST requests';
Write-Host 'Botnet nodes: 15,000 compromised hosts';
Write-Host '';
$endpoints = @(
  'GET / HTTP/1.1',
  'GET /search?q='+[guid]::NewGuid().ToString(),
  'POST /api/login (random credentials)',
  'GET /products?page='+(Get-Random -Min 1 -Max 99999),
  'POST /api/contact (large form data)',
  'GET /images/catalog.pdf (large file request)'
);
foreach($ep in $endpoints) {
  $rps = Get-Random -Min 100 -Max 500;
  Write-Host \"  $ep | $rps req/sec per bot\";
}
Write-Host '';
Write-Host 'Combined attack rate:';
Write-Host '  15,000 bots x 300 req/sec avg = 4,500,000 HTTP requests/sec';
Write-Host '  Web server: Apache/nginx max_connections exhausted';
Write-Host '  Application: Database connection pool drained';
Write-Host '  Effect: HTTP 503 Service Unavailable for all users'"

powershell -ep bypass -c "
# Slowloris attack simulation (connection exhaustion)
Write-Host '=== Slowloris Attack (Slow HTTP) ===';
Write-Host \"Target: www.{companyName}.com:443\";
Write-Host 'Method: Slow, incomplete HTTP headers';
Write-Host '';
Write-Host 'Attack mechanism:';
Write-Host '  1. Open TCP connection to target';
Write-Host '  2. Send partial HTTP request header';
Write-Host '  3. Send additional header bytes every 10 seconds';
Write-Host '  4. Never complete the request';
Write-Host '  5. Server keeps connection open waiting for complete header';
Write-Host '';
for($i=1; $i -le 5; $i++) {
  Write-Host \"  Connection $i`: GET / HTTP/1.1`r`nHost: www.{companyName}.com`r`nX-Header-$i`: $(Get-Random)...[INCOMPLETE]\";
}
Write-Host '';
Write-Host 'Active slow connections: 1,000';
Write-Host 'Apache MaxClients (default): 256';
Write-Host 'nginx worker_connections: 1024';
Write-Host '';
Write-Host 'Result: All connection slots consumed by slow requests';
Write-Host '        Legitimate users get Connection Refused'"

powershell -ep bypass -c "
# Monitor target status during attack
Write-Host '=== Target Status Monitoring ===';
Write-Host '';
$attacks = @(
  @{Time='10:00:00';Type='Normal';RPS=150;Status='200 OK';Latency='45ms'},
  @{Time='10:05:00';Type='SYN Flood Start';RPS=50150;Status='200 OK';Latency='850ms'},
  @{Time='10:10:00';Type='+UDP Flood';RPS=100150;Status='200/503';Latency='3200ms'},
  @{Time='10:15:00';Type='+DNS Amplification';RPS=150150;Status='503';Latency='timeout'},
  @{Time='10:20:00';Type='+HTTP Flood';RPS=4650150;Status='503/RST';Latency='timeout'},
  @{Time='10:25:00';Type='+Slowloris';RPS=4650150;Status='Connection Refused';Latency='N/A'},
  @{Time='10:30:00';Type='All vectors active';RPS=4650150;Status='UNREACHABLE';Latency='N/A'}
);
Write-Host 'Time     | Attack Vector        | Req/sec   | HTTP Status        | Latency';
Write-Host '---------|---------------------|-----------|--------------------|---------';
foreach($a in $attacks) {
  Write-Host \"$($a.Time) | $($a.Type.PadRight(19)) | $($a.RPS.ToString('N0').PadLeft(9)) | $($a.Status.PadRight(18)) | $($a.Latency)\";
}
Write-Host '';
Write-Host 'Total attack bandwidth: ~2.1 Gbps';
Write-Host 'Target status: COMPLETELY OFFLINE';
Write-Host 'Estimated business impact: $45,000/hour downtime cost'"

powershell -ep bypass -c "
Write-Host '=== DDoS Attack Complete Summary ===';
Write-Host '';
Write-Host 'Attack Vectors Used:';
Write-Host '  Layer 3/4 (Network):';
Write-Host '    [1] SYN Flood      : 50K pps  | TCP connection exhaustion';
Write-Host '    [2] UDP Flood      : 100K pps | 1.12 Gbps bandwidth saturation';
Write-Host '    [3] DNS Amplify    : 20K qps  | 480 Mbps reflected traffic';
Write-Host '  Layer 7 (Application):';
Write-Host '    [4] HTTP Flood     : 4.5M rps | Web/DB resource exhaustion';
Write-Host '    [5] Slowloris      : 1K conn  | Connection slot exhaustion';
Write-Host '';
Write-Host 'Defense Recommendations:';
Write-Host '  [1] CDN/DDoS mitigation service (Cloudflare, AWS Shield)';
Write-Host '  [2] Rate limiting + SYN cookies at edge';
Write-Host '  [3] BCP38 (ingress filtering) at ISP level';
Write-Host '  [4] WAF with bot detection + CAPTCHA';
Write-Host '  [5] Connection timeout tuning + keepalive limits';
Write-Host '  [6] Anycast DNS + geo-distributed infrastructure';
Write-Host '  [7] Incident response plan + ISP emergency contacts'"
